.achievement-stat .stat-label {
  font-size: 0.8rem;
  color: var(--gray-500);
  margin-top: 6px;
  line-height: 1.3;
}

/* FAQ Accordion */
.faq-section {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 48px;
}

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  margin-bottom: 8px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  background: none;
  border: none;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  text-align: left;
  transition: var(--transition);
}
.faq-question:hover { background: var(--gray-50); }

.faq-arrow {
  font-size: 0.7rem;
  color: var(--gray-500);
  transition: transform 0.25s ease;
  flex-shrink: 0;
}
.faq-item.open .faq-arrow { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.open .faq-answer {
  max-height: 200px;
  padding: 0 20px 16px;
}
.faq-answer p {
  font-size: 0.9rem;
  color: var(--text-light);
  line-height: 1.6;
}

/* === Footer === */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,0.8);
  margin-top: auto;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 24px;
}

.footer-mission {
  font-size: 0.85rem;
  line-height: 1.7;
  margin-bottom: 24px;
  max-width: 800px;
}

.footer-trending h4 {
  color: var(--white);
  font-size: 0.85rem;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.trending-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}
.trending-tags a {
  padding: 5px 12px;
  background: rgba(255,255,255,0.08);
  border-radius: 4px;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.7);
  transition: var(--transition);
}
.trending-tags a:hover { background: rgba(255,255,255,0.15); color: var(--white); text-decoration: none; }

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding-top: 16px;
  border-top: 1px solid rgba(255,255,255,0.1);
}
.footer-links a {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.6);
}
.footer-links a:hover { color: var(--white); }

/* === Responsive === */
@media (max-width: 900px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }

  .featured-card { flex-direction: column; }
  .featured-card .card-thumb { width: 100%; min-height: 180px; }
  .featured-card .card-title { font-size: 1.15rem; }

  .curriculum-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .initiative-list { grid-template-columns: 1fr; }
  .achievements-grid { grid-template-columns: repeat(2, 1fr); }
  .resource-list { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .main-nav { display: none; }
  .hamburger { display: flex; }
  .mobile-menu { display: block; }

  .search-bar { display: none; }

  .article-grid { grid-template-columns: 1fr; }
  .achievements-grid { grid-template-columns: 1fr; }

  .popular-tags-scroll { gap: 8px; }

  .page-header h1 { font-size: 1.5rem; }
  .donate-hero h1 { font-size: 1.6rem; }

  .featured-card .card-thumb { min-height: 140px; }
  .featured-card .card-body { padding: 20px; }
  .featured-card .card-title { font-size: 1.05rem; }

  .amount-selector { flex-wrap: wrap; }
  .amount-btn { padding: 10px 16px; font-size: 0.9rem; }

  .footer-inner { padding: 28px 20px; }
  .header-inner { padding: 0 16px; }
}
